-- Aqar Kuwait: normalized core schema and tenant-aware row security.
create extension if not exists pgcrypto;
create extension if not exists pg_trgm;

create type public.app_role as enum ('super_admin','manager','sales_agent','call_center','data_entry','accountant','viewer');
create type public.property_status as enum ('available','sold','lost');

create table public.roles (id uuid primary key default gen_random_uuid(), name text not null unique, name_ar text not null, is_system boolean not null default false, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email text not null, role_id uuid references public.roles(id), manager_id uuid references public.profiles(id), team_id uuid, is_active boolean not null default true, phone_visible boolean not null default false, price_visible boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.permissions (id uuid primary key default gen_random_uuid(), module text not null, action text not null, unique(module,action));
create table public.role_permissions (role_id uuid not null references public.roles(id) on delete cascade, permission_id uuid not null references public.permissions(id) on delete cascade, allowed boolean not null default false, primary key(role_id,permission_id));

create table public.lookups (id uuid primary key default gen_random_uuid(), type text not null, code integer not null, name_ar text not null, name_en text, is_active boolean not null default true, created_at timestamptz not null default now(), unique(type,code), unique(type,name_ar));
create table public.clients (id uuid primary key default gen_random_uuid(), name text not null, source text, notes text, tags text[] not null default '{}', assigned_to uuid references public.profiles(id), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.client_phones (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, phone text not null, normalized_phone text not null, label text, is_primary boolean not null default false, unique(client_id,normalized_phone));
create index client_phones_normalized_idx on public.client_phones(normalized_phone);
create table public.properties (id uuid primary key default gen_random_uuid(), code text not null unique, client_id uuid references public.clients(id), type_id uuid references public.lookups(id), offer_type_id uuid references public.lookups(id), location_type_id uuid references public.lookups(id), area_id uuid references public.lookups(id), block text, plot text, street text, avenue text, floor text, building_type text, area_m2 numeric(12,2) check(area_m2 is null or area_m2>=0), asking_price_kwd numeric(15,3) check(asking_price_kwd is null or asking_price_kwd>=0), details text, notes text, assigned_to uuid references public.profiles(id), created_by uuid not null references public.profiles(id), status public.property_status not null default 'available', entry_date date not null default current_date, latitude double precision, longitude double precision, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index properties_search_trgm on public.properties using gin (code gin_trgm_ops, block gin_trgm_ops, plot gin_trgm_ops);
create index properties_area_status_idx on public.properties(area_id,status,entry_date desc);
create index properties_assigned_idx on public.properties(assigned_to,entry_date desc);
create index properties_price_idx on public.properties(asking_price_kwd) where deleted_at is null;
create table public.property_phones (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, phone text not null, normalized_phone text not null, position smallint not null default 1 check(position between 1 and 3), unique(property_id,position));
create index property_phones_normalized_idx on public.property_phones(normalized_phone);
create table public.property_images (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, storage_path text not null, caption text, sort_order integer not null default 0, created_at timestamptz not null default now());
create table public.property_documents (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, storage_path text not null, file_name text not null, content_type text, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.requests (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id), type_id uuid references public.lookups(id), area_id uuid references public.lookups(id), min_size numeric(12,2), max_size numeric(12,2), min_price numeric(15,3), max_price numeric(15,3), notes text, assigned_to uuid references public.profiles(id), status text not null default 'open', created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.matches (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.requests(id) on delete cascade, property_id uuid not null references public.properties(id) on delete cascade, score numeric(5,2) not null, notified_at timestamptz, created_at timestamptz not null default now(), unique(request_id,property_id));
create table public.follow_ups (id uuid primary key default gen_random_uuid(), client_id uuid references public.clients(id), property_id uuid references public.properties(id), assigned_to uuid not null references public.profiles(id), due_at timestamptz not null, title text not null, notes text, completed_at timestamptz, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.appointments (id uuid primary key default gen_random_uuid(), client_id uuid references public.clients(id), property_id uuid references public.properties(id), assigned_to uuid not null references public.profiles(id), starts_at timestamptz not null, ends_at timestamptz, title text not null, location text, notes text, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.comments (id uuid primary key default gen_random_uuid(), property_id uuid references public.properties(id) on delete cascade, client_id uuid references public.clients(id) on delete cascade, body text not null, mentions uuid[] not null default '{}', created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), check(property_id is not null or client_id is not null));
create table public.favorites (user_id uuid not null references public.profiles(id) on delete cascade, property_id uuid not null references public.properties(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,property_id));
create table public.ads (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, platform text not null, published_at date, cost_kwd numeric(12,3), status text not null default 'draft', url text, notes text, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id text, before_data jsonb, after_data jsonb, metadata jsonb not null default '{}', ip_hash text, created_at timestamptz not null default now());
create index audit_logs_created_idx on public.audit_logs(created_at desc);
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, body text, link text, read_at timestamptz, created_at timestamptz not null default now());
create table public.saved_filters (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null, filters jsonb not null, is_shared boolean not null default false, created_at timestamptz not null default now());

create table public.import_batches (id uuid primary key default gen_random_uuid(), created_by uuid not null references public.profiles(id), file_name text not null, storage_path text, target text not null, status text not null default 'staged', total_rows integer not null default 0, created_count integer not null default 0, updated_count integer not null default 0, skipped_count integer not null default 0, failed_count integer not null default 0, rollback_until timestamptz not null default now()+interval '30 days', started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table public.import_rows (id bigint generated always as identity primary key, batch_id uuid not null references public.import_batches(id) on delete cascade, row_number integer not null, raw_row jsonb not null, mapped_row jsonb, status text not null default 'pending', error_message text, entity_id uuid, before_data jsonb, created_at timestamptz not null default now(), processed_at timestamptz, unique(batch_id,row_number));
create index import_rows_resume_idx on public.import_rows(batch_id,status,row_number);
create table public.import_mappings (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null, target text not null, mapping jsonb not null, created_at timestamptz not null default now());
create table public.value_mappings (id uuid primary key default gen_random_uuid(), lookup_type text not null, source_value text not null, lookup_id uuid not null references public.lookups(id), created_by uuid references public.profiles(id), created_at timestamptz not null default now(), unique(lookup_type,source_value));

create or replace function public.current_app_role() returns text language sql stable security definer set search_path=public as $$ select r.name from profiles p join roles r on r.id=p.role_id where p.id=auth.uid() and p.is_active $$;
create or replace function public.can_view_record(owner_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select case public.current_app_role() when 'super_admin' then true when 'manager' then true when 'viewer' then true when 'accountant' then true when 'data_entry' then true when 'sales_agent' then owner_id=auth.uid() or exists(select 1 from profiles me join profiles owner on owner.id=owner_id where me.id=auth.uid() and me.team_id is not null and me.team_id=owner.team_id) when 'call_center' then owner_id=auth.uid() else false end $$;
create or replace function public.has_permission(p_module text,p_action text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles p join roles r on r.id=p.role_id join role_permissions rp on rp.role_id=r.id join permissions x on x.id=rp.permission_id where p.id=auth.uid() and p.is_active and rp.allowed and x.module=p_module and x.action=p_action) or public.current_app_role() in ('super_admin','manager') $$;
create or replace function public.audit_row_change() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into audit_logs(actor_id,action,entity_type,entity_id,before_data,after_data) values(auth.uid(),lower(tg_op),tg_table_name,coalesce(new.id::text,old.id::text),case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end); return coalesce(new,old); end $$;

-- Profiles and role grants are never client-editable. Keep authorization in PostgreSQL.
alter table profiles enable row level security; alter table roles enable row level security; alter table permissions enable row level security; alter table role_permissions enable row level security;
alter table lookups enable row level security; alter table clients enable row level security; alter table client_phones enable row level security; alter table properties enable row level security; alter table property_phones enable row level security; alter table property_images enable row level security; alter table property_documents enable row level security; alter table requests enable row level security; alter table matches enable row level security; alter table follow_ups enable row level security; alter table appointments enable row level security; alter table comments enable row level security; alter table favorites enable row level security; alter table ads enable row level security; alter table audit_logs enable row level security; alter table notifications enable row level security; alter table saved_filters enable row level security; alter table import_batches enable row level security; alter table import_rows enable row level security; alter table import_mappings enable row level security; alter table value_mappings enable row level security;

create policy "profiles self or managers read" on profiles for select using(id=auth.uid() or current_app_role() in ('super_admin','manager'));
create policy "profiles manager update" on profiles for update using(current_app_role()='super_admin');
create policy "roles readable by authenticated" on roles for select to authenticated using(true);
create policy "permissions readable by authenticated" on permissions for select to authenticated using(true);
create policy "role permissions admin only" on role_permissions for all using(current_app_role()='super_admin') with check(current_app_role()='super_admin');
create policy "active lookups readable" on lookups for select to authenticated using(is_active or current_app_role() in ('super_admin','manager'));
create policy "lookup admins edit" on lookups for all using(current_app_role() in ('super_admin','manager')) with check(current_app_role() in ('super_admin','manager'));
create policy "clients scoped read" on clients for select using(deleted_at is null and can_view_record(assigned_to));
create policy "clients scoped create" on clients for insert with check(auth.uid()=created_by and has_permission('clients','create'));
create policy "clients scoped update" on clients for update using(can_view_record(assigned_to) and has_permission('clients','edit')) with check(can_view_record(assigned_to));
create policy "clients scoped delete" on clients for delete using(current_app_role() in ('super_admin','manager') and has_permission('clients','delete'));
create policy "client phones visible to authorized roles" on client_phones for select using(exists(select 1 from clients c join profiles me on me.id=auth.uid() where c.id=client_id and can_view_record(c.assigned_to) and me.phone_visible));
create policy "client phones scoped insert" on client_phones for insert with check(exists(select 1 from clients c where c.id=client_id and can_view_record(c.assigned_to)));
create policy "client phones scoped update" on client_phones for update using(exists(select 1 from clients c where c.id=client_id and can_view_record(c.assigned_to))) with check(exists(select 1 from clients c where c.id=client_id and can_view_record(c.assigned_to)));
create policy "client phones scoped delete" on client_phones for delete using(exists(select 1 from clients c where c.id=client_id and can_view_record(c.assigned_to)));
create policy "properties scoped read" on properties for select using(deleted_at is null and can_view_record(assigned_to));
create policy "properties scoped create" on properties for insert with check(auth.uid()=created_by and has_permission('properties','create'));
create policy "properties scoped update" on properties for update using(can_view_record(assigned_to) and has_permission('properties','edit')) with check(can_view_record(assigned_to));
create policy "properties scoped delete" on properties for delete using(current_app_role() in ('super_admin','manager') and has_permission('properties','delete'));
create policy "property phones visible to authorized roles" on property_phones for select using(exists(select 1 from properties p join profiles me on me.id=auth.uid() where p.id=property_id and can_view_record(p.assigned_to) and me.phone_visible));
create policy "property phones scoped insert" on property_phones for insert with check(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to)));
create policy "property phones scoped update" on property_phones for update using(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to))) with check(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to)));
create policy "property phones scoped delete" on property_phones for delete using(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to)));
create policy "property images scoped" on property_images for all using(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to))) with check(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to)));
create policy "property documents scoped" on property_documents for all using(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to))) with check(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to)));
create policy "requests scoped" on requests for all using(can_view_record(assigned_to)) with check(auth.uid()=created_by or current_app_role() in ('super_admin','manager'));
create policy "matches scoped" on matches for select using(exists(select 1 from requests r where r.id=request_id and can_view_record(r.assigned_to)));
create policy "followups assigned" on follow_ups for all using(can_view_record(assigned_to)) with check(can_view_record(assigned_to));
create policy "appointments assigned" on appointments for all using(can_view_record(assigned_to)) with check(can_view_record(assigned_to));
create policy "comments scoped read" on comments for select using((property_id is not null and exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to))) or (client_id is not null and exists(select 1 from clients c where c.id=client_id and can_view_record(c.assigned_to))));
create policy "comments scoped write" on comments for insert with check(auth.uid()=created_by);
create policy "favorites owner" on favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "ads scoped" on ads for all using(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to))) with check(exists(select 1 from properties p where p.id=property_id and can_view_record(p.assigned_to)));
create policy "audit admins read" on audit_logs for select using(current_app_role() in ('super_admin','manager'));
create policy "notifications owner" on notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "saved filters owner or shared" on saved_filters for select using(user_id=auth.uid() or is_shared);
create policy "saved filters manage own" on saved_filters for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "import batches scoped" on import_batches for select using(created_by=auth.uid() or current_app_role() in ('super_admin','manager'));
create policy "import batch writer" on import_batches for insert with check(auth.uid()=created_by and has_permission('imports','import'));
create policy "import batch admin update" on import_batches for update using(created_by=auth.uid() or current_app_role() in ('super_admin','manager'));
create policy "import rows batch scope" on import_rows for select using(exists(select 1 from import_batches b where b.id=batch_id and (b.created_by=auth.uid() or current_app_role() in ('super_admin','manager'))));
create policy "import rows batch writer" on import_rows for all using(exists(select 1 from import_batches b where b.id=batch_id and b.created_by=auth.uid() and has_permission('imports','import'))) with check(exists(select 1 from import_batches b where b.id=batch_id and b.created_by=auth.uid() and has_permission('imports','import')));
create policy "mapping owner" on import_mappings for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "value mapping authenticated read" on value_mappings for select to authenticated using(true);
create policy "value mapping admin write" on value_mappings for all using(current_app_role() in ('super_admin','manager','data_entry')) with check(current_app_role() in ('super_admin','manager','data_entry'));

create trigger clients_audit after insert or update or delete on clients for each row execute function audit_row_change();
create trigger properties_audit after insert or update or delete on properties for each row execute function audit_row_change();
create trigger requests_audit after insert or update or delete on requests for each row execute function audit_row_change();

insert into roles(name,name_ar,is_system) values ('super_admin','مدير النظام',true),('manager','مدير',true),('sales_agent','مندوب مبيعات',true),('call_center','مركز الاتصال',true),('data_entry','مدخل بيانات',true),('accountant','محاسب',true),('viewer','مشاهد',true) on conflict(name) do nothing;
insert into permissions(module,action) select m,a from unnest(array['properties','clients','requests','follow_ups','appointments','ads','reports','imports','lookups','users','audit']) m cross join unnest(array['view','create','edit','delete','export','import','assign']) a on conflict do nothing;
insert into role_permissions(role_id,permission_id,allowed) select r.id,p.id,case when r.name in ('super_admin','manager') then true when r.name='data_entry' then p.action in ('view','create','edit','import') when r.name='sales_agent' then p.action in ('view','create','edit','assign') and p.module in ('properties','clients','requests','follow_ups','appointments') when r.name='call_center' then p.action in ('view','create','edit') and p.module in ('clients','follow_ups','appointments') when r.name='accountant' then p.action in ('view','export') and p.module in ('properties','reports') else p.action='view' end from roles r cross join permissions p on conflict(role_id,permission_id) do nothing;
insert into lookups(type,code,name_ar,name_en) values
 ('area',101,'الأندلس','Al-Andalus'),('area',102,'الروضة','Al-Rawda'),('area',103,'صباح الأحمد','Sabah Al-Ahmad'),('area',104,'السليبخات','Al-Sulaibikhat'),('area',105,'العارضية','Al-Ardiya'),('area',106,'شرق','Sharq'),('area',107,'السالمية','Salmiya'),('area',108,'حولي','Hawally'),('area',109,'الفروانية','Farwaniya'),('area',110,'الجابرية','Jabriya'),('property_type',201,'أرض','Land'),('property_type',202,'بيت','House'),('property_type',203,'شقة','Apartment'),('property_type',204,'تجاري','Commercial'),('offer_type',301,'للبيع','For sale'),('offer_type',302,'للإيجار','For rent'),('offer_type',303,'للبدل','For exchange'),('offer_type',304,'مطلوب شراء','Wanted to buy'),('location_type',401,'زاوية شارعين','Corner'),('location_type',402,'بطن وظهر','Back-to-back'),('location_type',403,'ثلاث جهات','Three sides'),('location_type',404,'شارع واحد','Single street') on conflict(type,code) do nothing;

-- New authenticated users start with least privilege; promote the first administrator via SQL.
create or replace function public.bootstrap_profile() returns trigger language plpgsql security definer set search_path=public as $$
begin
 insert into public.profiles(id,full_name,email,role_id)
 select new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),new.email,r.id
 from public.roles r where r.name='viewer';
 return new;
end $$;
create trigger auth_user_profile_bootstrap after insert on auth.users for each row execute function public.bootstrap_profile();
